CREATE FUNCTION calculate_rcp(vehicle_reg VARCHAR)
RETURNS VARCHAR AS $ $
DECLARE 
    distance_travelled NUMERIC,
    distance_remaining NUMERIC,
    completion_status VARCHAR;

BEGIN
    -- Get the distance travelled and remaining for the vehicle
    SELECT 
        distdonekm INTO distance_travelled, 
        distleftkm INTO distance_remaining
    FROM transportinfo
    WHERE vehiclereg = vehicle_reg;

    -- Determine the completion status
    IF distance_travelled > distance_remaining THEN
        completion_status := 'Completed';
    ELSE
        completion_status := 'Not Completed';
    END IF;

    RETURN completion_status;
END;
$ $ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION calc_effective_leverage(
    levscale DECIMAL(3,0),
    possum DECIMAL(12,3),
    collsum DECIMAL(12,3)
) RETURNS DECIMAL(12,3) AS $ $
BEGIN
    RETURN (possum / collsum) * levscale;
END;
$ $ LANGUAGE plpgsql;

